let playing;
function playToggle(on,force=false){if(!force&&!S.on.ToggleSound)return;let pair=soundBank[val('ToggleSound','Mode')];if(!pair)return;if(playing){playing.pause();playing.currentTime=0}playing=new Audio(pair[on?'on':'off']);playing.volume=val('ToggleSound','Volume')/100;playing.play().catch(e=>log('Audio: '+e.message))}

function open(o){if(!o)return;let i=opened.indexOf(o);if(i>=0){opened.splice(i,1);o.box.classList.remove('open');o.b.classList.remove('open');o.box.inert=true;return}if(opened.length===2)open(opened[0]);opened.push(o);o.box.inert=false;o.box.classList.add('open');o.b.classList.add('open')}

function settings(m){let box=document.createElement('section'),inner=document.createElement('div');box.className='opts';box.inert=true;box.append(inner);
for(let[n,type,def,lo,hi,step]of defs[m]||[]){let label=document.createElement('label'),multi=['Players','Messages','Allowed Players','Join','Leave','Chat','Message'].includes(n),f=document.createElement(type==='select'?'select':type==='text'&&multi?'textarea':'input'),v=val(m,n)??def;
label.append(document.createTextNode(n));if(m==='ClickGUI'&&n.startsWith('Shader ')&&n!=='Shader Mode')label.dataset.shaderSetting='1';
if(type==='select'){for(let x of lo)f.add(new Option(x,x));f.value=v;}else{if(f.tagName!=='TEXTAREA')f.type=type;if(type==='range'){f.min=lo;f.max=hi;f.step=step}if(type==='checkbox')f.checked=!!v;else f.value=v;}
if(['Target','Player','IP'].includes(n)&&f.tagName==='INPUT'){if(n!=='IP')f.setAttribute('list','online-names');f.autocomplete='off'}
if(type==='color'){let hex=document.createElement('output');hex.textContent=v;label.append(hex);f.addEventListener('input',()=>hex.textContent=f.value)}
let out=document.createElement('output');if(type==='range'){out.value=v;label.append(out)}label.append(f);inner.append(label);
const changed=()=>{S.val[m+'/'+n]=type==='checkbox'?f.checked:type==='range'?+f.value:f.value;out.value=S.val[m+'/'+n];saved();appearance();if(remoteCatalog[m]&&!remoteCatalog[m].action)queueSettings(m);if(m.endsWith('HUD'))renderHUD()};
f.oninput=changed;f.onchange=changed;}
if(m==='ToggleSound'){let bar=document.createElement('div');bar.className='soundtests';for(let[name,on]of[['▶ ON',true],['▶ OFF',false]]){let b=document.createElement('button');b.className='plain';b.textContent=name;b.onclick=()=>playToggle(on,true);bar.append(b)}inner.append(bar)}
if(m==='ClickGUI'){let l=document.createElement('label');l.textContent='Wallpaper';let f=document.createElement('input');f.type='file';f.accept='image/png,image/jpeg,image/webp';f.onchange=()=>{let file=f.files[0];if(!file)return;if(file.size>8388608)return status('画像は8MB以下です',true);let r=new FileReader();r.onload=()=>{document.body.style.backgroundImage='url("'+r.result+'")';saveWallpaper(r.result)};r.readAsDataURL(file)};l.append(f);inner.prepend(l)}
if(['Connect','TPA','PublicChat','PrivateChat','CustomCommand'].includes(m)){let b=document.createElement('button');b.className='plain';b.textContent=m==='Connect'?'Save server':m==='TPA'?'Send TPA':'Send';b.onclick=()=>controlAction(m);inner.append(b)}
if(remoteCatalog[m]&&!defs[m].length){let note=document.createElement('small');note.textContent='Left click: ON / OFF';inner.append(note)}return box}

for(const [g,ms]of Object.entries(groups)){let p=document.createElement('section'),h=document.createElement('button'),l=document.createElement('div');p.className='panel';h.className='cap';h.innerHTML=g+'<span>⠿</span>';l.className='list';p.append(h,l);space.append(p);panels.push([g,p,h]);for(const m of ms){let b=document.createElement('button');b.textContent=labelOf(m);b.className='row';l.append(b);let account=g==='Account';if(account){let dot=document.createElement('i');dot.className='dot';b.prepend(dot)}let box=account?null:settings(m),o={b,box,m,account,g};if(box)l.append(box);rows.push(o);b.onclick=()=>handleClick(o);b.oncontextmenu=e=>{e.preventDefault();if(box)open(o)};b.onkeydown=e=>{if(e.key==='F2'&&box){e.preventDefault();open(o)}}}
let drag=null,t;h.onpointerdown=e=>{if(e.button!==0)return;h.setPointerCapture(e.pointerId);drag={dx:(e.clientX-p.getBoundingClientRect().left)/(val('ClickGUI','Scale')/100),dy:(e.clientY-p.getBoundingClientRect().top)/(val('ClickGUI','Scale')/100),active:false};t=setTimeout(()=>{if(!drag)return;drag.active=true;p.classList.add('drag');p.style.zIndex=++z},240)};h.onpointermove=e=>{if(!drag?.active)return;const r=space.getBoundingClientRect();place(p,(e.clientX-r.left)/(val('ClickGUI','Scale')/100)-drag.dx+space.scrollLeft,(e.clientY-r.top)/(val('ClickGUI','Scale')/100)-drag.dy+space.scrollTop)};function end(){clearTimeout(t);if(drag?.active){S.pos[g]=[parseFloat(p.style.left),parseFloat(p.style.top)];saved()}p.classList.remove('drag');drag=null}h.onpointerup=h.onpointercancel=h.onlostpointercapture=end}
function place(p,x,y){x=Math.max(0,Math.min(x,space.clientWidth-p.offsetWidth));y=Math.max(0,Math.min(y,space.clientHeight-50));p.style.left=x+'px';p.style.top=y+'px';p.style.setProperty('--avail',Math.max(30,space.clientHeight-y-48)+'px')}

function layout(){const w=space.clientWidth,gap=8,pw=Math.min(168,Math.max(116,Math.floor((w-38)/8)-gap)),cols=Math.max(1,Math.min(8,Math.floor((w-22)/(pw+gap))));const map={Account:[0,0],Control:[1,0],Combat:[2,0],Movement:[3,0],Player:[4,0],HUD:[5,0],GUI:[5,225],Chat:[6,0],Misc:[7,0],World:[7,240]};for(let[g,p]of panels){p.style.width=pw+'px';let[c,y]=map[g]||[0,400];if(c>=cols)y+=450*Math.floor(c/cols);place(p,...(S.pos[g]||[12+(c%cols)*(pw+gap),12+y]))}}

function paint(){for(const o of rows)o.b.classList.toggle('on',o.account?S.acc===o.m:!!S.on[o.m]);$('#lang').value=S.lang;$('#guide').textContent=tr('左：切替　／　右：設定　／　見出し長押し：移動','LMB toggle　/　RMB settings　/　Hold header to move');$('#reset').textContent=tr('配置を戻す','Reset layout');$('#history').textContent=tr('操作結果を開く ↗','Open activity ↗');$('#search').placeholder=tr('モジュール検索　/','Search modules　/')}
$('#search').oninput=e=>{let q=e.target.value.trim().toLowerCase();rows.forEach(o=>{let visible=o.account||(o.m+' '+labelOf(o.m)).toLowerCase().includes(q)||o.g.toLowerCase().includes(q);o.b.hidden=!visible;o.b.style.display=visible?'':'none';if(!visible&&opened.includes(o))open(o)})};$('#lang').onchange=e=>{S.lang=e.target.value;saved();paint()};$('#reset').onclick=()=>{S.pos={};saved();layout()};$('#history').onclick=()=>{$('#heading').textContent=tr('操作結果','Activity');$('#logs').replaceChildren();for(const [t,s] of logs){let p=document.createElement('p'),time=document.createElement('time');time.textContent=t;p.append(time,s);$('#logs').append(p)}$('#result').showModal()};$('#back').onclick=()=>$('#result').close();window.onkeydown=e=>{if(e.key==='/'&&!e.target.matches('input,select')){e.preventDefault();$('#search').focus()}if(e.key==='Escape'&&!$('#result').open&&opened.length)open(opened.at(-1))};window.onresize=layout;paint();appearance();layout();log('Nocturne / local session');

const cv=$('#snow'),sc=cv.getContext('2d'),particles=Array.from({length:300},()=>[Math.random(),Math.random(),Math.random()*.85+.15]);let last=0,flakes=0;

let flowTime=0;
function frame(ms){requestAnimationFrame(frame);if(ms-last<24||document.hidden)return;let dt=Math.min(.1,(ms-last)/1000);last=ms;flowTime+=dt;
const angle=val('ClickGUI','Shader Direction')*Math.PI/180,speed=val('ClickGUI','Shader Speed')*9;
document.documentElement.style.setProperty('--flow-x',(flowTime*speed*Math.cos(angle))+'px');document.documentElement.style.setProperty('--flow-y',(flowTime*speed*Math.sin(angle))+'px');
flakes+=dt*val('Weather','Speed');let w=space.clientWidth,h=space.clientHeight;if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}sc.clearRect(0,0,w,h);
if(S.on.Weather){let mode=val('Weather','Mode'),size=val('Weather','Size'),wind=val('Weather','Wind');sc.globalAlpha=val('Weather','Opacity')/100;sc.fillStyle=val('Weather','Color');sc.strokeStyle=mode==='Lava'?'#ff954f':val('Weather','Color');for(let[a,b,c]of particles.slice(0,val('Weather','Density'))){let x=((a*w+flakes*wind*30)%w+w)%w,y=(b*h+flakes*(mode==='Rain'?130:mode==='Lava'?-25:12+26*c))%h;y=(y+h)%h;sc.beginPath();if(mode==='Rain'){sc.lineWidth=size*.7;sc.moveTo(x,y);sc.lineTo(x+wind*3,y+size*12);sc.stroke()}else if(mode==='Crystal'){let d=size*(1+3*c);sc.moveTo(x,y-d*2);sc.lineTo(x+d,y);sc.lineTo(x,y+d*2);sc.lineTo(x-d,y);sc.closePath();sc.stroke()}else if(mode==='Lava'){sc.fillStyle=c>.5?'#ffb14d':'#f26937';sc.fillRect(x,y,size*(1+c*2),size*(1+c*2))}else{sc.arc(x,y,size*(.5+1.3*c),0,7);sc.fill()}}sc.globalAlpha=1}}

requestAnimationFrame(frame);

let csrf='',liveState=null,mapTimer=null,mapBusy=false,unlocked=false,pollTimer=null,saving=new Set(),pendingRefresh=false;
const localModules=new Set(['ClickGUI','Weather','NameTags','ToggleSound','MapHUD','HealthHUD','BpsHUD','HotbarHUD','PlayerListHUD']);
const actionModules=new Set(['WorldMap','Inventory','ChatQueue','CustomCommand']);
const online=()=>location.protocol==='https:'||location.hostname==='localhost';
function status(s,error=false){$('#statusline').textContent=s;$('#statusline').style.color=error?'#ff9090':'#d4cadd';log(s)}
function lockUI(msg){unlocked=false;clearInterval(pollTimer);pollTimer=null;document.body.classList.add('locked');$('#gate').hidden=false;$('#gateerror').textContent=msg||''}
async function rawApi(path,data){const headers={};if(data!==undefined){headers['Content-Type']='application/json';headers['X-CSRF-Token']=csrf;headers['X-Request-Id']=crypto.randomUUID()}let r=await fetch(path,{credentials:'same-origin',headers,...(data===undefined?{}:{method:'POST',body:JSON.stringify(data)})});let j;try{j=await r.json()}catch{throw Error('サーバーの応答を確認できません。GitHubの更新ファイルとURLを確認してください')}if(!r.ok){if(r.status===401&&unlocked)lockUI(j.error);throw Error(j.error||String(r.status))}return j}
async function api(path,data){if(!online()||!unlocked)throw Error('先にDiscord認証とパスワード入力を完了してください');return rawApi(path.replace(/^\/api\//,'/api/desktop/'),data)}
async function session(){const s=await api('/api/state');csrf=s.csrf;liveState=s;return s}
function target(){if(S.acc==='All Bots')return 'all';if(S.acc==='IGN PvP')return 'ign';if(S.acc==='2b2e')return '2b2e';const b=liveState?.bots.find(b=>b.name===S.acc);if(!b)throw Error('Botを選択してください');return String(b.id)}
function selected(){if(!liveState)return[];let t;try{t=target()}catch{return[]}return liveState.bots.filter(b=>t==='all'||String(b.id)===t||b.server===t)}
function moduleValues(m){return Object.fromEntries((defs[m]||[]).map(d=>[d[0],val(m,d[0])]))}
function setAccountRows(){const p=panels.find(x=>x[0]==='Account')?.[1],list=p?.querySelector('.list');if(!list)return;for(let i=rows.length-1;i>=0;i--)if(rows[i].account)rows.splice(i,1);list.replaceChildren();for(const name of ['All Bots','IGN PvP','2b2e',...liveState.bots.map(b=>b.name)]){let b=document.createElement('button');b.className='row';b.textContent=name;let o={b,m:name,account:true,g:'Account'};rows.push(o);list.append(b);b.onclick=()=>{S.acc=name;saved();syncRemote(true);renderHUD()};b.oncontextmenu=e=>{e.preventDefault();let bot=liveState.bots.find(b=>b.name===name);if(bot)accountMenu(bot)}}}
function syncRemote(load=false){
 if(!liveState)return;const ids=new Set(selected().map(b=>b.id)),ms=liveState.desktopModules.filter(x=>ids.has(x.id));
 for(const [m,c]of Object.entries(remoteCatalog)){if(c.action)continue;let values=ms.map(x=>!!x.states[m]);if(!moduleIntents.has(m))S.on[m]=values.length>0&&values.every(Boolean);let o=rows.find(x=>!x.account&&x.m===m);o?.b.classList.toggle('mixed',values.some(Boolean)&&!values.every(Boolean));if(load){for(let d of defs[m]||[])S.val[m+'/'+d[0]]=ms[0]?.values[m]?.[d[0]]??d[2];if(o&&opened.includes(o)){o.box.replaceWith(o.box=settings(m));o.box.classList.add('open');o.box.inert=false}}}
 paint();$('#connect').textContent=(liveState.profile?.name||'Discord')+' / Logout';$('#connection').textContent='LIVE · '+selected().filter(b=>b.connected).length+'/'+selected().length+' ONLINE';
}
async function refreshRemote(){if(pendingRefresh||!unlocked)return;pendingRefresh=true;try{await session();syncRemote();refreshSuggestions();renderHUD()}catch(e){status(e.message,true)}finally{pendingRefresh=false}}

const moduleIntents=new Map(),settingsTimers=new Map();
function queueSettings(m){clearTimeout(settingsTimers.get(m));settingsTimers.set(m,setTimeout(()=>saveModule(m,null),90))}
async function saveModule(m,enabled){if(!unlocked)return lockUI();let t;try{t=target()}catch(e){return status(e.message,true)}
let old=moduleIntents.get(m);moduleIntents.set(m,{target:t,enabled:enabled===null&&old?old.enabled:enabled,values:moduleValues(m)});
if(enabled!==null){S.on[m]=enabled;paint();playToggle(enabled)}if(saving.has(m))return;saving.add(m);
try{while(moduleIntents.has(m)){const intent=moduleIntents.get(m);try{let r=await api('/api/module',{module:m,...intent});if(r.desktopModules&&liveState)liveState.desktopModules=r.desktopModules;if(moduleIntents.get(m)===intent)moduleIntents.delete(m);syncRemote();status(r.result||'更新しました',r.ok===false);if(r.ok===false)showResults(r.result);}catch(e){if(moduleIntents.get(m)===intent)moduleIntents.delete(m);status(e.message,true);try{await session();syncRemote();refreshSuggestions();renderHUD()}catch{}showResults(e.message)}}}finally{saving.delete(m)}
}

function showResults(message){$('#heading').textContent='Operation result';$('#logs').replaceChildren();let p=document.createElement('p');p.textContent=message;$('#logs').append(p);if(!$('#result').open)$('#result').showModal()}
async function handleClick(o){let m=o.m;if(m==='Disconnect')return connectionCommand('disconnect');if(m==='Stop')return connectionCommand('stop');if(m==='MicrosoftLogin')return $('#mcauth').onclick();if(m==='BackNow')return instant('back','');if(['Friendlist','EnemyList'].includes(m))return relationUI(m);if(['KitNow','WorldNow'].includes(m))return instantUI(m);if(m==='Config')return configUI();if(['Connect','TPA','PublicChat','PrivateChat','Players'].includes(m)){if(m==='Connect')return connectionCommand('connect');if(m==='Players')return showPlayers();if(!opened.includes(o))open(o);return}if(o.account){S.acc=m;saved();syncRemote(true);return}if(localModules.has(m)){S.on[m]=!S.on[m];if(m==='ClickGUI')S.on.ClickGUI=true;playToggle(S.on[m],m==='ToggleSound');saved();paint();appearance();renderHUD();return}if(!unlocked){lockUI();return}
 if(m==='WorldMap'){openMap();return}if(m==='Inventory'){showInventory();return}if(m==='ChatQueue'){showResults(selected().map(b=>'[Bot'+b.id+'] '+b.name+' · '+JSON.stringify(b.chatQueue)).join('\n'));return}
 if(m==='CustomCommand'){if(!opened.includes(o))open(o);return}return saveModule(m,!S.on[m]);}
async function showInventory(){await refreshRemote();$('#heading').textContent='Inventory';$('#logs').replaceChildren();for(let b of selected()){let title=document.createElement('h3');title.textContent='[Bot'+b.id+'] '+b.name;$('#logs').append(title);let armor=document.createElement('p');armor.textContent='Armor: '+b.armor.map(x=>x.name||'—').join(' / ')+' · Offhand: '+(b.offhand.name||'—');$('#logs').append(armor);for(let x of b.inventory.filter(x=>x.count)){let line=document.createElement('button');line.className='plain';line.textContent=(x.slot+1)+': '+x.name+' ×'+x.count+(x.selected?' ✓':'');line.onclick=async()=>{try{await api('/api/equip',{target:String(b.id),slot:x.slot});await refreshRemote();showInventory()}catch(e){status(e.message,true)}};$('#logs').append(line)}}if(!$('#result').open)$('#result').showModal()}
async function connectionCommand(cmd){if(!unlocked)return lockUI();try{let r=await api('/api/command',{target:target(),command:cmd});await refreshRemote();showResults(r.result)}catch(e){showResults(e.message)}}
$('#botconnect').onclick=()=>connectionCommand('connect');$('#botstop').onclick=()=>connectionCommand('stop');$('#botdisconnect').onclick=()=>connectionCommand('disconnect');
$('#mcauth').onclick=async()=>{try{if(selected().length!==1)throw Error('認証するBotを1体選択してください');let r=await api('/api/auth',{target:target()});showResults(r.message||JSON.stringify(r.authentication))}catch(e){showResults(e.message)}};
$('#connect').onclick=async()=>{if(!online())return connectServer();if(unlocked){try{await api('/api/logout',{})}catch{}lockUI();await initAuth()}else initAuth()};
function connectServer(){try{let u=new URL($('#serverurl').value);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&u.hostname==='localhost'))throw Error();location.href=u.origin+'/nocturne'}catch{$('#gateerror').textContent='https://から始まる管理WebのURLを指定してください'}}
$('#serverform').onsubmit=e=>{e.preventDefault();connectServer()};
$('#discordlogin').onclick=()=>{location.href='/api/oauth/start?returnTo=/nocturne'};
$('#codeform').onsubmit=async e=>{e.preventDefault();try{let r=await rawApi('/api/login',{code:$('#logincode').value});csrf=r.csrf;$('#logincode').value='';await initAuth()}catch(e){$('#gateerror').textContent=e.message}};
$('#passwordform').onsubmit=async e=>{e.preventDefault();let button=$('#unlockbutton');button.disabled=true;try{let auth=await rawApi('/api/desktop/access');csrf=auth.csrf;let p=$('#password').value;if(auth.setup&&p!==$('#passwordconfirm').value)throw Error('確認用パスワードが一致しません');let r=await rawApi('/api/desktop/access',{action:auth.setup?'setup':'unlock',password:p});csrf=r.csrf;$('#password').value=$('#passwordconfirm').value='';await enterMenu()}catch(e){$('#gateerror').textContent=e.message}finally{button.disabled=false}};
async function initAuth(){lockUI();$('#serverform').hidden=online();$('#discordsection').hidden=true;$('#passwordform').hidden=true;if(!online())return;try{let hash=new URLSearchParams(location.hash.slice(1)),code=hash.get('login');if(code){history.replaceState(null,'',location.pathname);let login=await rawApi('/api/login',{code});csrf=login.csrf;}let a=await rawApi('/api/desktop/access');csrf=a.csrf;if(a.unlocked)return enterMenu();$('#passwordform').hidden=false;$('#gatewho').textContent=a.profile?.name||'Discord';$('#passwordconfirm').hidden=!a.setup;$('#passwordconfirm').required=a.setup;$('#unlockbutton').textContent=a.setup?'パスワードを作成して開始':'Unlock';$('#passwordhint').textContent=a.setup?'初回：自分のパスワードを作成（10文字以上）':'自分のパスワードを入力してください';}
 catch(e){$('#discordsection').hidden=false;try{let info=await rawApi('/api/login-info');$('#discordlogin').disabled=!info.discordReady;$('#oauthhint').textContent=info.discordReady?'Discord Botで許可されたユーザーだけ利用できます':'Discord OAuth未設定：Discordの /web で発行されるコードでも認証できます。'}catch{$('#oauthhint').textContent='サーバーの更新ファイルとURLを確認してください'}}}
async function enterMenu(){unlocked=true;try{await session();document.body.classList.remove('locked');$('#gate').hidden=true;setAccountRows();if(!selected().length)S.acc='All Bots';syncRemote(true);refreshSuggestions();renderHUD();clearInterval(pollTimer);pollTimer=setInterval(refreshRemote,2500);status('認証済み · 設定とON/OFFをBotサーバーへ送信します')}catch(e){lockUI(e.message)}}
let wpDB;function wallpaperDB(){return new Promise((ok,no)=>{let r=indexedDB.open('asira-wallpaper',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function saveWallpaper(url){try{let db=await wallpaperDB();db.transaction('images','readwrite').objectStore('images').put(url,'wallpaper')}catch(e){status('壁紙の保存に失敗しました',true)}}
wallpaperDB().then(db=>{let r=db.transaction('images').objectStore('images').get('wallpaper');r.onsuccess=()=>{if(r.result)document.body.style.backgroundImage='url("'+r.result+'")'}}).catch(()=>{});

let md=document.createElement('dialog');md.id='mapwindow';md.innerHTML='<h2>World Map</h2><div class="maptoolbar"><select id="mapworld"></select><select id="mapdim"><option value="0">Overworld</option><option value="1">Nether</option><option value="2">End</option></select><select id="mapstep"><option value="1">Nearby</option><option value="4">Wide</option><option value="16">Overview</option></select><label>X <input id="mapx" type="number" value="0"></label><label>Z <input id="mapz" type="number" value="0"></label><label>Y <input id="mapy" type="number" value="127"></label><button id="maprefresh" class="plain">Refresh</button></div><p id="mapstatus">接続が必要です</p><canvas id="mapcanvas" width="800" height="560"></canvas><p><button id="mapclose" class="plain">← ClickGUI</button></p>';document.body.append(md);
$('#mapclose').onclick=()=>md.close();md.onclose=()=>{clearInterval(mapTimer);mapTimer=null};
async function openMap(){if(!md.open)md.showModal();try{await session();let {worlds}=await api('/api/maps');$('#mapworld').replaceChildren(...worlds.map(w=>new Option(w.name||w.host||w.key,w.key)));if(!worlds.length)throw Error('地形の記録がありません。Botを接続してください');await refreshMap();clearInterval(mapTimer);mapTimer=setInterval(()=>{if(md.open)refreshMap()},1500)}catch(e){$('#mapstatus').textContent=e.message}}
async function refreshMap(){if(mapBusy)return;mapBusy=true;try{let q={world:$('#mapworld').value,dimension:$('#mapdim').value,x:Math.round(Number($('#mapx').value)-64*Number($('#mapstep').value)),z:Math.round(Number($('#mapz').value)-64*Number($('#mapstep').value)),y:Math.round(Number($('#mapy').value)),step:$('#mapstep').value,size:128};let v=await api('/api/map?'+new URLSearchParams(q));let c=$('#mapcanvas'),g=c.getContext('2d'),scale=Math.min(c.width,c.height)/v.size,ox=(c.width-v.size*scale)/2;g.fillStyle='#101019';g.fillRect(0,0,c.width,c.height);for(let z=0;z<v.size;z++)for(let x=0;x<v.size;x++){let name=v.palette[v.cells[z*v.size+x]]||'';g.fillStyle=!name?'#1a1a25':/lava|magma/.test(name)?'#ec753b':/water/.test(name)?'#4375aa':/netherrack/.test(name)?'#854d54':/grass|leaves/.test(name)?'#65855c':/obsidian/.test(name)?'#423a55':'#797783';g.fillRect(ox+x*scale,z*scale,scale+.1,scale+.1)}g.strokeStyle='#ffffff30';g.lineWidth=.5;for(let i=0;i<=v.size;i++){g.beginPath();if((v.x+i*v.step)%16===0){g.moveTo(ox+i*scale,0);g.lineTo(ox+i*scale,v.size*scale)}if((v.z+i*v.step)%16===0){g.moveTo(ox,i*scale);g.lineTo(ox+v.size*scale,i*scale)}g.stroke()}for(let p of v.players||[]){let x=ox+(p.position.x-v.x)/v.step*scale,z=(p.position.z-v.z)/v.step*scale;if(x<ox||x>ox+v.size*scale||z<0||z>c.height)continue;g.fillStyle=p.relation==='friend'?val('NameTags','Friend Color'):p.relation==='enemy'?val('NameTags','Enemy Color'):val('NameTags','Player Color');g.beginPath();g.arc(x,z,4,0,7);g.fill();g.font='12px Segoe UI';if(S.on.NameTags!==false)g.fillText(p.name,x+7,z-5)}drawMap(v,c);$('#mapstatus').textContent='LIVE · '+new Date(v.at).toLocaleTimeString()+' · '+(v.players||[]).length+' players · 未記録部分は暗色';}catch(e){$('#mapstatus').textContent=e.message}finally{mapBusy=false}}
$('#maprefresh').onclick=refreshMap;for(let k of ['mapworld','mapdim','mapstep'])$('#'+k).onchange=refreshMap;

const suggestions=document.createElement('datalist');suggestions.id='online-names';document.body.append(suggestions);
function refreshSuggestions(){suggestions.replaceChildren(...[...new Set((liveState?.bots||[]).flatMap(b=>[b.name,...b.onlinePlayers]))].sort().map(n=>new Option(n,n)))}
function tools(title,build){$('#heading').textContent=title;$('#logs').replaceChildren();build($('#logs'));if(!$('#result').open)$('#result').showModal()}
function field(parent,name,type='text',value='',options){let l=document.createElement('label');l.className='toolfield';l.append(document.createTextNode(name));let f=document.createElement(options?'select':type==='textarea'?'textarea':'input');if(options)for(let x of options)f.add(new Option(x,x));else if(type!=='textarea')f.type=type;f.value=value;if(/Player|Target/i.test(name)&&f.tagName==='INPUT')f.setAttribute('list','online-names');l.append(f);parent.append(l);return f}
function button(parent,name,run){let b=document.createElement('button');b.className='plain';b.textContent=name;b.onclick=async()=>{try{await run()}catch(e){status(e.message,true);let p=document.createElement('p');p.textContent=e.message;parent.append(p)}};parent.append(b);return b}
async function controlAction(m){if(m==='CustomCommand')return saveModule(m,true);if(m==='Connect'){let custom=val(m,'Custom IP'),r=await api('/api/control',{action:'endpoint',target:target(),realm:val(m,'Server'),custom,host:val(m,'IP'),port:Number(val(m,'Port'))});status(r.result);await refreshRemote();return}
if(m==='TPA'){let r=await api('/api/control',{action:'tpa',target:target(),player:val(m,'Player'),kind:{Request:'request',Accept:'accept',Deny:'deny'}[val(m,'Action')]});status(r.result,r.ok===false);return}
if(m==='PublicChat'||m==='PrivateChat'){let r=await api('/api/chat',{target:target(),type:m==='PublicChat'?'public':'whisper',recipient:val(m,'Player'),message:val(m,'Message')});status(r.result,r.ok===false)}}
const accountPanel=panels.find(x=>x[0]==='Account');accountPanel[2].oncontextmenu=e=>{e.preventDefault();tools('Add Account',p=>{let name=field(p,'Gamertag (spaces supported)'),realm=field(p,'Server','text','ign',['ign','2b2e']);button(p,'Add account',async()=>{let r=await api('/api/control',{action:'add',name:name.value,realm:realm.value});await session();setAccountRows();syncRemote();status('Added: '+r.account.name);$('#result').close()})})};
function accountMenu(bot){tools('[Bot'+bot.id+'] '+bot.name,p=>{let name=field(p,'Account / Gamertag','text',bot.name);button(p,'Change account',async()=>{await api('/api/control',{action:'rename',target:String(bot.id),name:name.value});await session();setAccountRows();syncRemote(true);$('#result').close()});button(p,'Microsoft Login',async()=>{let r=await api('/api/auth',{target:String(bot.id)});showResults(r.message||JSON.stringify(r.authentication))});let confirm=field(p,'Delete: type gamertag exactly');button(p,'Delete account',async()=>{if(confirm.value!==bot.name)throw Error('削除するゲーマータグを正確に入力してください');let r=await api('/api/control',{action:'remove',target:String(bot.id),confirm:true});S.acc='All Bots';await session();setAccountRows();syncRemote(true);status(r.result);$('#result').close()})})}
function showPlayers(){tools('Online Players',p=>{for(let name of [...new Set(selected().flatMap(b=>b.onlinePlayers))].sort()){let row=document.createElement('div');row.className='playerrow';row.textContent=name;button(row,'TPA',async()=>{let r=await api('/api/control',{action:'tpa',target:target(),player:name,kind:'request'});status(r.result)});p.append(row)}})}
let itemAtlas;
if(online())fetch('/assets/items.json').then(r=>r.ok?r.json():null).then(x=>{itemAtlas=x}).catch(()=>{});
function icon(item){let n=document.createElement('span');n.className='itemicon';n.title=item?.name||'空き/未受信';let sp=itemAtlas?.items?.[item?.name];if(sp){n.style.backgroundImage='url(/assets/items.png)';n.style.backgroundSize=itemAtlas.width+'px '+itemAtlas.height+'px';n.style.backgroundPosition=-sp.x+'px '+-sp.y+'px';n.style.width=(sp.width||32)+'px';n.style.height=(sp.height||32)+'px';}else if(item?.name)n.textContent=item.name.replace('minecraft:','').slice(0,2);if(item?.count>1){let c=document.createElement('b');c.textContent=item.count;n.append(c)}return n}
async function showInventory(){await refreshRemote();tools('Inventory',p=>{for(let b of selected()){let h=document.createElement('h3');h.textContent='[Bot'+b.id+'] '+b.name;p.append(h);let gear=document.createElement('div');gear.className='inventorygear';for(let x of [...b.armor,b.offhand])gear.append(icon(x));p.append(gear);let grid=document.createElement('div');grid.className='inventorygrid';for(let x of b.inventory){let cell=document.createElement('button');cell.className='slot'+(x.selected?' selected':'');cell.title=(x.slot+1)+': '+(x.name||'未受信/空き');cell.append(icon(x));cell.onclick=async()=>{try{await api('/api/equip',{target:String(b.id),slot:x.slot});await showInventory()}catch(e){status(e.message,true)}};grid.append(cell)}p.append(grid)}})}
const hudNodes=new Map();S.hudPos??={};let hudBusy=false;
function makeHUD(m){let p=document.createElement('section');p.className='panel hudwidget';p.dataset.hud=m;let h=document.createElement('button');h.className='cap';h.textContent=labelOf(m);let content=document.createElement('div');content.className='hudcontent';p.append(h,content);space.append(p);let drag;h.onpointerdown=e=>{if(e.button!==0)return;h.setPointerCapture(e.pointerId);let sc=val('ClickGUI','Scale')/100,r=p.getBoundingClientRect();drag={x:(e.clientX-r.left)/sc,y:(e.clientY-r.top)/sc};p.style.zIndex=++z};h.onpointermove=e=>{if(!drag)return;let sc=val('ClickGUI','Scale')/100,r=space.getBoundingClientRect();place(p,(e.clientX-r.left)/sc-drag.x,(e.clientY-r.top)/sc-drag.y);S.hudPos[m]=[parseFloat(p.style.left),parseFloat(p.style.top)];saved()};h.onpointerup=h.onpointercancel=h.onlostpointercapture=()=>drag=null;return {p,h,content}}
function renderHUD(){if(!unlocked)return;for(let m of ['MapHUD','HealthHUD','BpsHUD','HotbarHUD','PlayerListHUD']){let node=hudNodes.get(m);if(!S.on[m]){if(node)node.p.hidden=true;continue}if(!node){node=makeHUD(m);hudNodes.set(m,node);place(node.p,...(S.hudPos[m]||[12+hudNodes.size*35,Math.max(30,space.clientHeight-280)]))}node.p.hidden=false;node.h.hidden=!val(m,'Title');node.p.style.setProperty('--alpha',val(m,'Opacity')/100);node.p.style.zoom=val(m,'Scale');if(m==='MapHUD'){if(!node.canvas){node.canvas=document.createElement('canvas');node.canvas.width=360;node.canvas.height=280;node.content.append(node.canvas)}continue}node.content.replaceChildren();for(let b of selected()){let r=document.createElement('div');r.className='hudbot';let title=document.createElement('div');title.textContent='[BOT'+b.id+'] '+b.name;if(b.face){let im=document.createElement('img');im.src=b.face;im.className='skinface';title.prepend(im)}r.append(title);
if(m==='HealthHUD'){let hp=b.health??null,red=document.createElement('div');red.className='hearts';if(hp===null)red.textContent='HP 未受信';else{for(let i=0;i<10;i++){let heart=document.createElement('span');heart.textContent=i*2+1<hp?'♥':i*2<hp?'◐':'♡';red.append(heart)}let text=document.createElement('small');text.textContent=' '+hp+'/20';red.append(text)}r.append(red);if(b.absorption>0){let gold=document.createElement('div');gold.className='goldhearts';gold.textContent='♥'.repeat(Math.ceil(b.absorption/2));r.append(gold)}}
if(m==='BpsHUD'){let n=document.createElement('b');n.textContent=Number(b.bps||0).toFixed(2)+' BPS';r.append(n)}
if(m==='HotbarHUD'){let hot=document.createElement('div');hot.className='hotbar';for(let x of b.inventory.slice(0,9)){let cell=document.createElement('div');cell.className='slot'+(x.selected?' selected':'');cell.append(icon(x));hot.append(cell)}r.append(hot)}
if(m==='PlayerListHUD'){let text=document.createElement('small');text.textContent=(b.onlinePlayers||[]).join(' · ')||'未受信';r.append(text)}node.content.append(r)}}}
async function updateHUDMap(){if(hudBusy||!unlocked||!S.on.MapHUD)return;let node=hudNodes.get('MapHUD');if(!node?.canvas)return;hudBusy=true;try{let {worlds}=await api('/api/maps'),bot=selected().find(b=>b.connected),world=worlds.find(w=>w.host===bot?.endpoint.host&&w.port===bot?.endpoint.port)||worlds[0];if(!world)throw Error('地形記録待ち');let mode=val('MapHUD','Dimension'),dim=mode==='Auto'?(bot?.dimension||0):['Overworld','Nether','End'].indexOf(mode),range=val('MapHUD','Range'),center=val('MapHUD','Follow Bot')?bot?.position:null;let v=await api('/api/map?'+new URLSearchParams({world:world.key,dimension:dim,x:Math.round((center?.x||0)-range/2),z:Math.round((center?.z||0)-range/2),y:127,size:range,step:1}));drawMap(v,node.canvas)}catch(e){let g=node.canvas.getContext('2d');g.clearRect(0,0,360,280);g.fillStyle='#cbc3d7';g.font='12px Segoe UI';g.fillText(e.message,15,30)}finally{hudBusy=false}}
setInterval(updateHUDMap,1800);
function terrainColor(n,y){if(!n)return null;if(/lava|magma/.test(n))return '#ea7748';if(/water/.test(n))return '#4b8fae';if(/grass|leaves|moss/.test(n))return '#7a976c';if(/netherrack|crimson/.test(n))return '#a06e72';if(/obsidian/.test(n))return '#56506a';if(/sand|end_stone/.test(n))return '#c2ba8e';if(/snow|quartz/.test(n))return '#d8d9d4';return '#8e9193'}
function drawMap(v,c){let g=c.getContext('2d'),scale=Math.min(c.width,c.height)/v.size,ox=(c.width-v.size*scale)/2,oy=(c.height-v.size*scale)/2;g.clearRect(0,0,c.width,c.height);g.fillStyle='#171923';g.fillRect(0,0,c.width,c.height);for(let z=0;z<v.size;z++)for(let x=0;x<v.size;x++){let i=z*v.size+x,color=terrainColor(v.palette[v.cells[i]],v.heights[i]);if(!color)continue;g.fillStyle=color;g.fillRect(ox+x*scale,oy+z*scale,scale+.1,scale+.1);if(x&&v.heights[i]>v.heights[i-1]+1){g.fillStyle='#0002';g.fillRect(ox+x*scale,oy+z*scale,Math.max(.5,scale*.2),scale)}}g.strokeStyle='#ffffff15';g.lineWidth=.5;for(let i=0;i<=v.size;i++){g.beginPath();if((v.x+i*v.step)%16===0){g.moveTo(ox+i*scale,oy);g.lineTo(ox+i*scale,oy+v.size*scale)}if((v.z+i*v.step)%16===0){g.moveTo(ox,oy+i*scale);g.lineTo(ox+v.size*scale,oy+i*scale)}g.stroke()}
for(let p of v.players||[]){let x=ox+(p.position.x-v.x)/v.step*scale,z=oy+(p.position.z-v.z)/v.step*scale;if(x<ox||x>ox+v.size*scale||z<oy||z>oy+v.size*scale)continue;g.fillStyle=p.relation==='friend'?val('NameTags','Friend Color'):p.relation==='enemy'?val('NameTags','Enemy Color'):val('NameTags','Player Color');g.beginPath();g.arc(x,z,p.own?4:3,0,7);g.fill();if(S.on.NameTags!==false){g.font='11px Segoe UI';g.fillText(p.name,x+6,z-5)}}g.font='11px Consolas';g.fillStyle='#ffffffb8';g.fillText('N',c.width/2,14);g.fillText(v.x+' , '+v.z,8,c.height-8)}
// Share only preferences and module values, never session credentials.
let configDirectory;
function configDocument(){const values={};for(let[m,ds]of Object.entries(defs))for(let[k]of ds)if(S.val[m+'/'+k]!==undefined)(values[m]??={})[k]=S.val[m+'/'+k];return {format:'asira-nocturne-config',version:1,name:'Asira',values,positions:S.pos,hud:S.hudPos,localEnabled:Object.fromEntries([...localModules].map(m=>[m,!!S.on[m]]))}}
function importConfig(data){if(data?.format!=='asira-nocturne-config'||data.version!==1||!data.values||typeof data.values!=='object')throw Error('Asira設定JSONを指定してください');const applied={};for(let[m,ds]of Object.entries(defs))for(let[k,type,def,lo,hi]of ds){let v=data.values[m]?.[k];if(v===undefined)continue;if(type==='range'&&!(typeof v==='number'&&Number.isFinite(v)&&v>=lo&&v<=hi)||type==='checkbox'&&typeof v!=='boolean'||type==='select'&&!lo.includes(v)||type==='color'&&!(typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v))||type==='text'&&!(typeof v==='string'&&v.length<=1000))throw Error(m+'/'+k+' の値が不正です');applied[m+'/'+k]=v}
Object.assign(S.val,applied);for(let[k,v]of Object.entries(data.positions||{}))if(panels.some(x=>x[0]===k)&&Array.isArray(v)&&v.length===2&&v.every(x=>Number.isFinite(x)&&x>=0))S.pos[k]=v;for(let[k,v]of Object.entries(data.hud||{}))if(k.endsWith('HUD')&&Array.isArray(v)&&v.length===2&&v.every(x=>Number.isFinite(x)&&x>=0))S.hudPos[k]=v;for(let m of localModules)if(typeof data.localEnabled?.[m]==='boolean')S.on[m]=data.localEnabled[m];saved();appearance();layout();paint();renderHUD();status('設定を読み込みました。BotのON/OFFは変更していません');return applied}
async function readConfig(file){if(!file||file.size>1048576)throw Error('1MB以下の設定JSONを指定してください');return importConfig(JSON.parse(await file.text()))}
function configUI(){tools('Config / Share',p=>{let name=field(p,'Config name','text','Asira'),drop=document.createElement('div');drop.className='dropzone';drop.textContent='ここに設定JSONをドラッグ / Drop config here';drop.tabIndex=0;drop.ondragover=e=>{e.preventDefault();drop.classList.add('over')};drop.ondragleave=()=>drop.classList.remove('over');drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('over');try{await readConfig(e.dataTransfer.files[0]);drop.textContent='✓ Config loaded'}catch(e){drop.textContent=e.message}};p.append(drop);let file=field(p,'Import JSON','file');file.accept='.json,application/json';file.onchange=async()=>{try{await readConfig(file.files[0])}catch(e){status(e.message,true)}};
button(p,'Export / Save',async()=>{let safe=name.value.replace(/[^a-z0-9_-]/ig,'_').slice(0,60)||'Asira',text=JSON.stringify({...configDocument(),name:safe},null,2);if(configDirectory){let h=await configDirectory.getFileHandle(safe+'.json',{create:true}),w=await h.createWritable();await w.write(text);await w.close();status('config/'+safe+'.json を保存しました')}else{let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=safe+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
button(p,'Choose config folder',async()=>{if(!window.showDirectoryPicker)throw Error('この環境ではフォルダーを選べません。Exportで保存できます');let root=await window.showDirectoryPicker({mode:'readwrite'});configDirectory=await root.getDirectoryHandle('config',{create:true});status('保存先configフォルダーを設定しました')});
button(p,'Send imported settings to selected bots',async()=>{for(let[m,c]of Object.entries(remoteCatalog))if(!c.action)await saveModule(m,null);status('選択Botへ設定の反映処理を完了しました')});let hint=document.createElement('small');hint.textContent='認証情報・壁紙画像は含めません。インポートでBotを自動起動しません。';p.append(hint)})}


let toolPanels=[],pointer={x:200,y:100};document.addEventListener('pointerdown',e=>pointer={x:e.clientX,y:e.clientY});
function tools(title,build){if(toolPanels.length>=2)toolPanels.shift().remove();let p=document.createElement('section');p.className='panel inline-tool';let cap=document.createElement('button');cap.className='cap';cap.textContent=title;let close=document.createElement('span');close.textContent='×';close.onclick=e=>{e.stopPropagation();p.remove();toolPanels=toolPanels.filter(x=>x!==p)};cap.append(close);let content=document.createElement('div');content.className='hudcontent';p.append(cap,content);space.append(p);toolPanels.push(p);let r=space.getBoundingClientRect(),sc=val('ClickGUI','Scale')/100;place(p,(pointer.x-r.left)/sc,(pointer.y-r.top)/sc);let drag;cap.onpointerdown=e=>{if(e.target===close)return;cap.setPointerCapture(e.pointerId);drag={x:e.clientX-p.getBoundingClientRect().left,y:e.clientY-p.getBoundingClientRect().top};p.style.zIndex=++z};cap.onpointermove=e=>{if(!drag)return;place(p,(e.clientX-r.left-drag.x)/sc,(e.clientY-r.top-drag.y)/sc)};cap.onpointerup=cap.onpointercancel=()=>drag=null;build(content);}
let toastNode=document.createElement('div');toastNode.id='center-notice';document.body.append(toastNode);let toastTimer;
function notify(message,error=false){clearTimeout(toastTimer);toastNode.textContent=String(message).slice(0,240);toastNode.dataset.error=String(error);toastNode.classList.remove('shown');void toastNode.offsetWidth;toastNode.classList.add('shown');toastTimer=setTimeout(()=>toastNode.classList.remove('shown'),1900)}
function status(s,error=false){log(s);notify(s,error)}
function showResults(s){notify(s)}
async function relationUI(m){await refreshRemote();tools(m,p=>{let input=field(p,'MCID');let add=button(p,'+ Add',async()=>{let r=await api('/api/control',{action:'relation',kind:m==='Friendlist'?'friend':'enemy',operation:'add',name:input.value});status(r.result);await refreshRemote();renderList()});let list=document.createElement('div');p.append(list);const renderList=()=>{list.replaceChildren();for(let name of liveState[m==='Friendlist'?'friends':'enemies']||[]){let row=document.createElement('div');row.className='playerrow';row.append(document.createTextNode(name));button(row,'×',async()=>{await api('/api/control',{action:'relation',kind:m==='Friendlist'?'friend':'enemy',operation:'remove',name});await refreshRemote();renderList()});list.append(row)}};renderList()})}
async function instant(kind,value){let r=await api('/api/control',{action:'instant',target:target(),kind,value});status(r.result)}
function instantUI(m){tools(m,p=>{let input=field(p,m==='KitNow'?'Kit':'World');button(p,'Go',()=>instant(m==='KitNow'?'kit':'world',input.value))})}

initAuth();
